import java.nio.file.*;
import java.util.*;
import java.util.jar.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
import com.google.gson.*;

/** Finds key contexts using independently recovered member records and key redundancy. */
public class InferReferenceKeys {
 record Expr(String symbol,long xor){}
 enum This { VALUE }
 static class Symbolic extends RestoreStrings.Constants {
  final Map<String,ClassNode> classes;
  Symbolic(Map<String,Object> constants,Map<String,ClassNode> classes){super(constants);this.classes=classes;}
  public RestoreStrings.V newParameterValue(boolean instance,int local,Type type){RestoreStrings.V v=super.newParameterValue(instance,local,type);if(type.equals(Type.LONG_TYPE))return new RestoreStrings.V(v.type,new Expr("arg:"+local,0));if(instance&&local==0)return new RestoreStrings.V(v.type,This.VALUE);return v;}
  String field(FieldInsnNode f){ClassNode c=classes.get(f.owner);if(c!=null)for(FieldNode v:c.fields)if(v.name.equals(f.name)&&v.desc.equals("J")&&(v.access&(Opcodes.ACC_FINAL|Opcodes.ACC_STATIC))==Opcodes.ACC_FINAL)return "field:"+f.owner+'.'+f.name;return null;}
  public RestoreStrings.V unaryOperation(AbstractInsnNode n,RestoreStrings.V value)throws AnalyzerException{RestoreStrings.V result=super.unaryOperation(n,value);if(n.getOpcode()==Opcodes.CHECKCAST&&value.value==This.VALUE)return new RestoreStrings.V(result.type,This.VALUE);if(n instanceof FieldInsnNode&&n.getOpcode()==Opcodes.GETFIELD&&value.value==This.VALUE){String symbol=field((FieldInsnNode)n);if(symbol!=null)return new RestoreStrings.V(result.type,new Expr(symbol,0));}return result;}
  public RestoreStrings.V binaryOperation(AbstractInsnNode n,RestoreStrings.V a,RestoreStrings.V b)throws AnalyzerException{RestoreStrings.V result=super.binaryOperation(n,a,b);if(n.getOpcode()==Opcodes.LXOR){if(a.value instanceof Expr e&&b.value instanceof Long l)return new RestoreStrings.V(result.type,new Expr(e.symbol,e.xor^l));if(b.value instanceof Expr e&&a.value instanceof Long l)return new RestoreStrings.V(result.type,new Expr(e.symbol,e.xor^l));if(a.value instanceof Expr x&&b.value instanceof Expr y&&x.symbol.equals(y.symbol))return new RestoreStrings.V(result.type,x.xor^y.xor);}return result;}
 }
 static class Candidate {long encoded;JsonObject record;}
 static List<ResolveReferences.Target> compatible(JsonObject row,InvokeDynamicInsnNode call,Map<String,ClassNode> classes){List<ResolveReferences.Target> result=new ArrayList<>();char op=call.name.charAt(0);boolean field=op=='e'||op==214||op=='R'||op=='Z';Type[] args=Type.getArgumentTypes(call.desc);Type desired=Type.getReturnType(call.desc);
  for(JsonElement e:row.getAsJsonArray("targets")){JsonObject t=e.getAsJsonObject();if(t.get("kind").getAsString().equals("field")!=field)continue;ResolveReferences.Target target=ResolveReferences.find(t.get("owner").getAsString(),t.get("name").getAsString(),t.get("descriptor").getAsString(),field,classes,new HashSet<>());if(target==null)continue;boolean statik=field?(op=='R'||op=='Z'):op==206;if(statik!=target.isStatic)continue;List<Type> wanted=new ArrayList<>();Type returned;if(field){boolean setter=op==214||op=='Z';if(!statik)wanted.add(Type.getObjectType(target.owner));if(setter)wanted.add(Type.getType(target.descriptor));returned=setter?Type.VOID_TYPE:Type.getType(target.descriptor);}else{if(!statik)wanted.add(Type.getObjectType(target.owner));wanted.addAll(Arrays.asList(Type.getArgumentTypes(target.descriptor)));returned=Type.getReturnType(target.descriptor);}if(wanted.size()!=args.length-2||!ResolveReferences.compatible(returned,desired))continue;boolean valid=true;for(int i=0;i<wanted.size();i++)valid&=ResolveReferences.compatible(args[i],wanted.get(i));if(valid)result.add(target);
  }return result;
 }
 public static void main(String[] args)throws Exception{
  Map<String,ClassNode> classes=new LinkedHashMap<>();try(JarFile jar=new JarFile(args[0])){for(JarEntry e:Collections.list(jar.entries()))if(e.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(jar.getInputStream(e).readAllBytes()).accept(c,0);classes.put(c.name,c);}}
  JsonObject state=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonObject();String dispatcher=state.keySet().iterator().next();Map<Integer,List<Candidate>> fingerprints=new HashMap<>();for(JsonElement item:JsonParser.parseString(Files.readString(Path.of(args[2]))).getAsJsonArray()){JsonObject row=item.getAsJsonObject();for(JsonElement key:row.getAsJsonArray("encodedKeys")){Candidate c=new Candidate();c.encoded=key.getAsLong();c.record=row;int f=(int)((c.encoded>>>48)^c.encoded)&65535;fingerprints.computeIfAbsent(f,k->new ArrayList<>()).add(c);}}
  Map<String,Object> constants=SpecializeKeys.constants(classes);List<Map<String,Object>> profiles=new ArrayList<>();int known=0,non48=0,knownMatched=0,unknown=0,candidateSites=0;long mask=(1L<<48)-1;
  for(ClassNode c:classes.values())if(c.name.startsWith("me/octo/client/"))for(MethodNode m:c.methods)if(m.instructions.size()>0){Frame<RestoreStrings.V>[] frames;try{frames=new Analyzer<>(new Symbolic(constants,classes)).analyze(c.name,m);}catch(AnalyzerException e){continue;}Map<String,Set<Long>> domains=new LinkedHashMap<>();Map<String,Integer> votes=new HashMap<>();List<Map<String,Object>> evidence=new ArrayList<>();AbstractInsnNode[] nodes=m.instructions.toArray();
   for(int at=0;at<nodes.length;at++)if(nodes[at] instanceof InvokeDynamicInsnNode call&&call.bsm.getOwner().equals(dispatcher)&&frames[at]!=null){Type[] arguments=Type.getArgumentTypes(call.desc);Frame<RestoreStrings.V> frame=frames[at];if(arguments.length<2||!arguments[arguments.length-1].equals(Type.LONG_TYPE)||!arguments[arguments.length-2].equals(Type.LONG_TYPE)||frame.getStackSize()<2)continue;Object first=frame.getStack(frame.getStackSize()-2).value,second=frame.getStack(frame.getStackSize()-1).value;if(!(first instanceof Long a))continue;boolean observed=second instanceof Long;long actual=observed?(Long)second:0;if(observed){known++;if(actual<0||actual>mask){non48++;continue;}}else if(!(second instanceof Expr)){unknown++;continue;}
    int fingerprint=(int)((a>>>48)^a)&65535;Set<Long> keys=new LinkedHashSet<>();List<Integer> slots=new ArrayList<>();for(Candidate candidate:fingerprints.getOrDefault(fingerprint,List.of()))if(!compatible(candidate.record,call,classes).isEmpty()){long b=(a^candidate.encoded)&mask;if((a^(b<<48|b))!=candidate.encoded)throw new AssertionError("Redundancy mismatch");keys.add(b);slots.add(candidate.record.get("slot").getAsInt());}
    if(observed){if(keys.contains(actual))knownMatched++;continue;}Expr expression=(Expr)second;if(keys.isEmpty())continue;candidateSites++;Set<Long> seeds=new LinkedHashSet<>();for(long b:keys)seeds.add(b^expression.xor);if(!domains.containsKey(expression.symbol))domains.put(expression.symbol,seeds);else domains.get(expression.symbol).retainAll(seeds);votes.merge(expression.symbol,1,Integer::sum);evidence.add(Map.of("instruction",at,"symbol",expression.symbol,"xor",expression.xor,"referenceSlots",slots,"candidateSeeds",seeds));
   }
   if(!m.name.equals("<clinit>")&&!m.name.contains("$recovered$")&&!m.name.contains("$inferred$")){Map<String,Long> bindings=new LinkedHashMap<>();for(var entry:domains.entrySet())if(entry.getValue().size()==1&&votes.get(entry.getKey())>=2&&(!m.name.equals("<init>")||entry.getKey().startsWith("arg:")))bindings.put(entry.getKey(),entry.getValue().iterator().next());if(!bindings.isEmpty())profiles.add(Map.of("owner",c.name,"name",m.name,"descriptor",m.desc,"bindings",bindings,"votes",votes,"evidence",evidence,"provenance","Member-table cryptanalysis, repeated-half key redundancy, and agreement across at least two call sites; runtime callers not established"));}
  }
  Map<String,Object> summary=Map.of("knownConstantKeySites",known,"knownNon48BitKeys",non48,"knownKeysMatchedCatalog",knownMatched,"unknownWithoutAffineExpression",unknown,"candidateSites",candidateSites,"inferredMethodContexts",profiles.size(),"keyModel","48-bit second argument, validated against observed constant-key sites; profiles are analysis contexts");Gson gson=new GsonBuilder().setPrettyPrinting().create();Files.writeString(Path.of(args[3]),gson.toJson(profiles));Files.writeString(Path.of(args[4]),gson.toJson(summary));System.out.println(gson.toJson(summary));
 }
}
